// Simple stylized adventurer, guardian, companion, slimes, and a rideable forest-stag.
const player=new THREE.Group();scene.add(player);let skin=mat(0xe4b995),cloth=mat(0x4e7892),capeMat=mat(0xa34f4d),leather=mat(0x554331),bladeMat=mat(0xd7d8c6,.35);const body=mesh(new THREE.CylinderGeometry(.42,.55,1.25,8),cloth,player,0,1.25,0);let head=mesh(new THREE.SphereGeometry(.38,12,10),skin,player,0,2.2,0);let hair=mesh(new THREE.SphereGeometry(.4,10,7),mat(0x58402f),player,0,2.42,-.07);hair.scale.set(1,.55,1);let cape=mesh(new THREE.ConeGeometry(.56,1.35,5),capeMat,player,0,1.2,-.44);cape.rotation.x=-.16;for(let s of [-1,1]){mesh(new THREE.CylinderGeometry(.16,.18,.72,7),cloth,player,s*.56,1.2,0).rotation.z=s*.3;mesh(new THREE.CylinderGeometry(.18,.22,.68,7),leather,player,s*.24,.4,0)}let sword=mesh(new THREE.BoxGeometry(.12,.95,.16),bladeMat,player,.65,1.25,.04);sword.rotation.z=-.42;player.position.set(0,0,14);
const companion=new THREE.Group();scene.add(companion);let wolfBody=mesh(new THREE.SphereGeometry(.55,10,8),mat(0x776a58),companion,0,.65,0);wolfBody.scale.set(1.3,.7,.75);let wolfHead=mesh(new THREE.SphereGeometry(.36,10,8),mat(0x897a64),companion,0,.91,.52);for(let s of [-1,1]){let ear=mesh(new THREE.ConeGeometry(.13,.42,5),mat(0x897a64),companion,s*.2,1.23,.48);ear.rotation.x=-.15;let eye=mesh(new THREE.SphereGeometry(.045,6,6),mat(0xffca6b),companion,s*.14,1,.82)}for(let i=0;i<4;i++){let leg=mesh(new THREE.CylinderGeometry(.1,.12,.52,6),mat(0x685b4b),companion,i%2?-.3:.3,.27,i<2?.25:-.3)}
const horse=new THREE.Group();scene.add(horse);let horseCoat=mat(0x76513a);mesh(new THREE.CapsuleGeometry(.5,.95,4,8),horseCoat,horse,0,1.1,0).rotation.z=Math.PI/2;mesh(new THREE.SphereGeometry(.37,10,8),horseCoat,horse,0,1.65,.78);for(let s of [-1,1])for(let z of [-.35,.35])mesh(new THREE.CylinderGeometry(.11,.14,.95,6),mat(0x493326),horse,s*.3,.48,z).rotation.z=s*.08;horse.visible=false;
const npc=new THREE.Group();scene.add(npc);npc.position.set(2,0,-13);mesh(new THREE.CylinderGeometry(.38,.48,1.3,8),mat(0x718567),npc,0,1.25,0);mesh(new THREE.SphereGeometry(.36,10,8),skin,npc,0,2.15,0);mesh(new THREE.ConeGeometry(.42,.55,5),mat(0x4d704f),npc,0,2.55,0);mesh(new THREE.BoxGeometry(.08,1.3,.08),wood,npc,.62,1.2,0);let nm=mesh(new THREE.SphereGeometry(.12,8,8),warm,npc,.62,1.95,0);nm.add(new THREE.PointLight(0xffba50,1,4));
const creatures=[];function slime(x,z,color,label){let g=new THREE.Group();scene.add(g);let m=new THREE.MeshStandardMaterial({color,roughness:.3,emissive:color,emissiveIntensity:.12});let b=mesh(new THREE.SphereGeometry(.8,14,10),m,g,0,.7,0);b.scale.set(1,.8,1);for(let s of [-1,1])mesh(new THREE.SphereGeometry(.09,7,6),mat(0x252a24),g,s*.25,.85,.58);g.position.set(x,0,z);creatures.push({g,hp:3,max:3,alive:true,label,phase:rand(0,6),x,z});}slime(-12,-19,0x85c88a,'Musgo-vivo');slime(13,-22,0x88c8be,'Limo cristalino');slime(8,-38,0xc3a3db,'Slime lunar');slime(-33,4,0xe5a46f,'Raposa-fagulha');slime(34,8,0x8cb5df,'Limo celeste');
// Craftable buildings are placed a few paces ahead and persist through the session.
const built=[];let buildMode=false,buildType=0;function buildStructure(type){let x=clamp(player.position.x+Math.sin(player.rotation.y)*4,-55,55),z=clamp(player.position.z+Math.cos(player.rotation.y)*4,-55,55);let g=new THREE.Group();g.position.set(x,0,z);scene.add(g);if(type===0){mesh(new THREE.CylinderGeometry(1.5,1.8,.4,10),stone,g,0,.25,0);mesh(new THREE.ConeGeometry(1.25,1.2,8),mat(0xd88249),g,0,1.05,0);mesh(new THREE.CylinderGeometry(.12,.16,1.25,6),wood,g,0,.8,0);let fire=mesh(new THREE.SphereGeometry(.25,8,8),warm,g,0,1.8,0);fire.add(new THREE.PointLight(0xff8033,2,9));}else{mesh(new THREE.BoxGeometry(3,1.3,2.5),wood,g,0,.75,0);mesh(new THREE.ConeGeometry(2.4,1.3,4),roof,g,0,2,0).rotation.y=Math.PI/4;mesh(new THREE.BoxGeometry(.7,.7,.1),mat(0x7bbbaa),g,0,1,1.3)}built.push(g);state.inventory[type===0?'Madeira':'Pedra']-=type===0?3:2;notify(type===0?'Fogueira construída!':'Abrigo construído!');buildMode=false;document.querySelector('#buildbtn').classList.remove('selected');updateInventory()}

