input.newString:
built.push(g);state.inventory[type===0?'Madeira':'Pedra']-=type===0?3:2;notify(type===0?'Fogueira construída!':'Abrigo construído!');buildMode=false;document.querySelector('#buildbtn').classList.remove('selected');updateInventory()}
const state={hp:100,mp:80,xp:0,level:1,gold:42,kills:0,accepted:false,done:false,companionStay:false,mounted:false,inventory:{'Poção':2,'Madeira':5,'Pedra':4,'Cristal':1,'Ervas':3},race:'Humana',className:'Guardião',hair:'Castanho',skinTone:'Clara'};
const $=s=>document.querySelector(s);let toastTimer;function notify(t){const el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function updateInventory(){ $('#gold').textContent=state.gold;$('#level').textContent=state.level;$('#xpbar').style.width=`${state.xp}%`;$('#xptext').textContent=`${state.xp} / 100`;$('#hpbar').style.width=`${state.hp}%`;$('#hptext').textContent=`${state.hp} / 100`;$('#mpbar').style.width=`${state.mp}%`;$('#mptext').textContent=`${state.mp} / 100`;$('#petstatus').textContent=state.companionStay?'Guardando posição':'Sempre ao seu lado';let count=creatures.slice(0,3).filter(c=>!c.alive).length;if(state.done){$('#questtitle').textContent='O vale está em paz';$('#questdesc').textContent='A floresta agradece sua coragem. Explore, construa e descubra os segredos do vale.';$('#queststep').textContent='Missão concluída';$('#questcount').textContent='✓';$('#questbar').style.width='100%'}else if(state.accepted){$('#questtitle').textContent='Proteja a clareira';$('#questdesc').textContent='Afaste os slimes sombrios que rondam a árvore ancestral.';$('#queststep').textContent='Derrote criaturas';$('#questcount').textContent=`${count}/3` ;$('#questbar').style.width=`${count/3*100}%`}else{$('#questtitle').textContent='O chamado da clareira';$('#questdesc').textContent='Encontre a guardiã Elowen na clareira e ajude a proteger a floresta.';$('#queststep').textContent='Fale com Elowen';$('#questcount').textContent='0/1';$('#questbar').style.width='0%'}}
function gainXP(n){state.xp+=n;if(state.xp>=100){state.xp-=100;state.level++;state.hp=100;state.mp=100;notify(`Nível ${state.level}! Você ficou mais forte.`)}updateInventory()}
function defeat(c){if(!c.alive)return;c.alive=false;c.g.position.y=-20;state.kills++;state.gold+=5;state.inventory['Ervas']++;gainXP(24);notify(`${c.label} derrotado · +24 EXP · +5 moedas`);updateInventory();}
function attack(power=1,range=4){if($('#panel').classList.contains('open')||$('#dialog').classList.contains('open'))return;let target=null,d=range;for(const c of creatures)if(c.alive){let n=player.position.distanceTo(c.g.position);if(n<d){d=n;target=c}}if(target){target.hp-=power;target.g.scale.setScalar(1.12);setTimeout(()=>target.g.scale.setScalar(1),100);if(target.hp<=0)defeat(target);else notify(`${target.label} · ${target.hp}/${target.max} ♥`)}else{player.rotation.y+=.16;}}
function magic(){if(state.mp<28){notify('Mana insuficiente.');return}state.mp-=28;let hit=0;for(const c of creatures){if(c.alive&&player.position.distanceTo(c.g.position)<7){c.hp-=2;hit++;if(c.hp<=0)defeat(c)}}updateInventory();notify(hit?`Pulso arcano atingiu ${hit} criatura(s)!`:'Pulso arcano lançado');}
function drink(){if(!state.inventory['Poção']){notify('Sem poções no inventário.');return}state.inventory['Poção']--;state.hp=Math.min(100,state.hp+45);updateInventory();notify('Poção usada · vida restaurada')}
function interact(){if($('#panel').classList.contains('open'))return;let d=player.position.distanceTo(npc.position);if(d<4){$('#dialog').classList.add('open');return}for(let c of creatures)if(!c.alive&&player.position.distanceTo(c.g.position)<4){state.inventory['Cristal']++;notify('Você coletou um cristal brilhante.');c.g.position.y=-50;updateInventory();return}if(buildMode){buildStructure(buildType);return}notify('Não há nada para interagir por perto.')}
function toggleMount(){state.mounted=!state.mounted;horse.visible=state.mounted;if(state.mounted){horse.position.copy(player.position);horse.position.y=0;player.position.y=.25;notify('Montaria: Corcel da Aurora')}else{player.position.y=0;notify('Você desmontou.')} }
function followCompanion(){state.companionStay=!state.companionStay;updateInventory();notify(state.companionStay?'Brasa vai guardar esta posição.':'Brasa voltou a acompanhar você.')}
$('#dialogaccept').onclick=()=>{state.accepted=true;$('#dialog').classList.remove('open');updateInventory();notify('Missão aceita · Derrote 3 criaturas na clareira!')};$('#dialoglater').onclick=$('#closedialog').onclick=()=>$('#dialog').classList.remove('open');
function openPanel(type){let title=$('#paneltitle'),body=$('#panelbody');if(type==='map'){title.textContent='Mapa do Vale';body.innerHTML='<div class="maplarge"><span class="mapplace" style="left:47%;top:12%">Árvore Ancestral</span><span class="mapplace" style="left:67%;top:45%">Vila do Carvalho</span><span class="mapplace" style="left:10%;top:75%">Lago Espelhado</span><span class="mapdot">📍</span></div><p class="buildnote" style="margin-top:12px">Você está no Vale Verdejante. A clareira fica ao norte, junto à árvore ancestral.</p>'}else if(type==='inventory'){title.textContent='Mochila & Recursos';body.innerHTML=`<div class="grid">${Object.entries(state.inventory).map(([k,v])=>`<div class="item"><span class="big">${({'Poção':'🧪','Madeira':'🪵','Pedra':'🪨','Cristal':'💎','Ervas':'🌿'})[k]}</span><strong>${k}</strong><small>Quantidade: ${v}</small></div>`).join('')}</div><p class="buildnote" style="margin-top:14px">Materiais para construção: fogueira (3 🪵) · abrigo (2 🪨). Encontre cristais e ervas pela floresta.</p>`}else{title.textContent='Seu aventureiro';body.innerHTML=`<div class="tabrow"><button class="tab active" data-tab="status">Status</button><button class="tab" data-tab="custom">Personalizar</button></div><div id="statusview"><div class="row"><span>Raça</span><strong>${state.race}</strong></div><div class="row"><span>Classe</span><strong>${state.className}</strong></div><div class="row"><span>Nível & experiência</span><strong>${state.level} · ${state.xp}/100 EXP</strong></div><div class="row"><span>Criaturas derrotadas</span><strong>${state.kills}</strong></div><div class="row"><span>Companheiro</span><strong>Brasa, lobo da floresta</strong></div><div class="row"><span>Montaria</span><strong>Corcel da Aurora</strong></div></div><div id="customview" style="display:none"><p class="buildnote">Escolha uma raça, classe e visual. Suas escolhas são aplicadas no personagem.</p><div class="eyebrow">Raça</div><div class="classes" style="margin:8px 0 15px">${[['Humana','👤'],['Elfa','🧝'],['Anã','🛡️'],['Fae','🧚']].map(([n,i])=>`<button class="choice ${state.race===n?'active':''}" data-race="${n}"><span>${i}</span>${n}</button>`).join('')}</div><div class="eyebrow">Classe</div><div class="classes" style="margin:8px 0 15px">${[['Guardião','⚔️'],['Arcanista','🔮'],['Batedora','🏹']].map(([n,i])=>`<button class="choice ${state.className===n?'active':''}" data-class="${n}"><span>${i}</span>${n}</button>`).join('')}</div><div class="eyebrow">Cabelo</div><div class="classes" style="margin:8px 0 15px"><button class="choice active" data-hair="Castanho">Castanho</button><button class="choice" data-hair="Dourado">Dourado</button><button class="choice" data-hair="Prateado">Prateado</button></div><div class="eyebrow">Tom de pele</div><div class="classes" style="margin-top:8px"><button class="choice active" data-skin="Clara">Clara</button><button class="choice" data-skin="Morena">Morena</button><button class="choice" data-skin="Ébano">Ébano</button></div></div>`;body.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{body.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));$('#statusview').style.display=b.dataset.tab==='status'?'block':'none';$('#customview').style.display=b.dataset.tab==='custom'?'block':'none'});body.querySelectorAll('[data-race]').forEach(b=>b.onclick=()=>{state.race=b.dataset.race;body.querySelectorAll('[data-race]').forEach(x=>x.classList.toggle('active',x===b));notify(`Raça alterada: ${state.race}`)});body.querySelectorAll('[data-class]').forEach(b=>b.onclick=()=>{state.className=b.dataset.class;body.querySelectorAll('[data-class]').forEach(x=>x.classList.toggle('active',x===b));notify(`Classe: ${state.className}`)});body.querySelectorAll('[data-hair]').forEach(b=>b.onclick=()=>{state.hair=b.dataset.hair;hair.material.color.set(state.hair==='Dourado'?0xd4a74e:state.hair==='Prateado'?0xc5cbd0:0x58402f);body.querySelectorAll('[data-hair]').forEach(x=>x.classList.toggle('active',x===b))});body.querySelectorAll('[data-skin]').forEach(b=>b.onclick=()=>{state.skinTone=b.dataset.skin;skin.color.set(state.skinTone==='Morena'?0xb97852:state.skinTone==='Ébano'?0x734937:0xe4b995);body.querySelectorAll('[data-skin]').forEach(x=>x.classList.toggle('active',x===b))})}$('#panel').classList.add('open')}
$('[data-panel="map"]').onclick=()=>openPanel('map');$('[data-panel="inventory"]').onclick=()=>openPanel('inventory');$('[data-panel="status"]').onclick=()=>openPanel('status');$('#closepanel').onclick=()=>$('#panel').classList.remove('open');

